      isArchived: false,
    }), docs: "Project this task belongs to" })

@ReferenceField({ type: () => User, load: true, filter: () => ({
      roles: {
        elemMatch: { in: [Role.Developer, Role.Manager, Role.Admin] },
      },
    }), docs: "User assigned to work on this task" })

fields.filter:
